import React, { useState, useRef, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon } from 'lucide-react';

const MONTH_NAMES = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];
const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

function getDaysInMonth(year, month) {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstWeekday(year, month) {
  // 0 = воскресенье, 1 = понедельник, ... 6 = суббота
  // нам нужен формат 0 = понедельник
  const w = new Date(year, month, 1).getDay();
  return w === 0 ? 6 : w - 1;
}

// value: "YYYY-MM-DD" (ISO) или "MM-DD" (без года)
// mode: "full" — с годом, "month-day" — без года
export default function CalendarInput({ value, onChange, mode = 'full', placeholder }) {
  const [open, setOpen] = useState(false);
  const [viewYear, setViewYear] = useState(() => {
    if (value && mode === 'full') return parseInt(value.slice(0, 4), 10);
    return new Date().getFullYear();
  });
  const [viewMonth, setViewMonth] = useState(() => {
    if (value && mode === 'full') return parseInt(value.slice(5, 7), 10) - 1;
    if (value && mode === 'month-day') return parseInt(value.slice(0, 2), 10) - 1;
    return new Date().getMonth();
  });
  const wrapRef = useRef(null);

  useEffect(() => {
    function onDocClick(e) {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) {
        setOpen(false);
      }
    }
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, []);

  const daysInMonth = getDaysInMonth(viewYear, viewMonth);
  const firstWeekday = getFirstWeekday(viewYear, viewMonth);

  // Собираем ячейки: пустые перед первым днём + дни месяца
  const cells = [];
  for (let i = 0; i < firstWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);
  // добиваем до кратности 7
  while (cells.length % 7 !== 0) cells.push(null);

  const handleDayClick = (day) => {
    if (!day) return;
    const mm = String(viewMonth + 1).padStart(2, '0');
    const dd = String(day).padStart(2, '0');
    if (mode === 'full') {
      onChange(`${viewYear}-${mm}-${dd}`);
    } else {
      onChange(`${mm}-${dd}`);
    }
    setOpen(false);
  };

  const prevMonth = () => {
    if (viewMonth === 0) { setViewMonth(11); setViewYear(viewYear - 1); }
    else setViewMonth(viewMonth - 1);
  };
  const nextMonth = () => {
    if (viewMonth === 11) { setViewMonth(0); setViewYear(viewYear + 1); }
    else setViewMonth(viewMonth + 1);
  };

  // Выбранный день для подсветки
  let selectedDay = null;
  if (value) {
    if (mode === 'full' && value.length >= 10) {
      const y = parseInt(value.slice(0, 4), 10);
      const m = parseInt(value.slice(5, 7), 10) - 1;
      const d = parseInt(value.slice(8, 10), 10);
      if (y === viewYear && m === viewMonth) selectedDay = d;
    } else if (mode === 'month-day' && value.length >= 5) {
      const m = parseInt(value.slice(0, 2), 10) - 1;
      const d = parseInt(value.slice(3, 5), 10);
      if (m === viewMonth) selectedDay = d;
    }
  }

  // Отображение в поле ввода
  const displayValue = (() => {
    if (!value) return '';
    if (mode === 'full' && value.length >= 10) {
      const [y, m, d] = value.split('-');
      return `${d}.${m}.${y}`;
    }
    if (mode === 'month-day' && value.length >= 5) {
      const [m, d] = value.split('-');
      return `${d}.${m}`;
    }
    return value;
  })();

  return (
    <div className="calendar-input" ref={wrapRef}>
      <div className="calendar-input-field" onClick={() => setOpen(!open)}>
        <span className={displayValue ? '' : 'muted'}>
          {displayValue || placeholder || 'Выберите дату'}
        </span>
        <CalendarIcon size={18} className="calendar-input-icon" />
      </div>

      {open && (
        <div className="calendar-popup">
          <div className="calendar-head">
            <button type="button" className="calendar-nav" onClick={prevMonth} aria-label="Предыдущий месяц">
              <ChevronLeft size={16} />
            </button>

            <div className="calendar-title">
              <span className="calendar-month">{MONTH_NAMES[viewMonth]}</span>
              {mode === 'full' && (
                <span className="calendar-year">{viewYear}</span>
              )}
            </div>

            <button type="button" className="calendar-nav" onClick={nextMonth} aria-label="Следующий месяц">
              <ChevronRight size={16} />
            </button>
          </div>

          <div className="calendar-weekdays">
            {WEEKDAYS.map((w) => <div key={w} className="calendar-weekday">{w}</div>)}
          </div>

          <div className="calendar-grid">
            {cells.map((day, i) => (
              <button
                type="button"
                key={i}
                className={`calendar-day ${!day ? 'empty' : ''} ${day === selectedDay ? 'selected' : ''}`}
                onClick={() => handleDayClick(day)}
                disabled={!day}
              >
                {day || ''}
              </button>
            ))}
          </div>

          {value && (
            <button
              type="button"
              className="calendar-clear"
              onClick={() => { onChange(''); setOpen(false); }}
            >
              Очистить
            </button>
          )}
        </div>
      )}
    </div>
  );
}