import React, { useEffect, useState } from 'react';

const STATS_URL = 'https://gist.githubusercontent.com/rrt-portal/c5e4f699ef9f28eb57dff81649f9bac3/raw/rrt-stats.json';

export function normalizeNick(s) {
  if (!s) return '';
  return String(s)
    .replace(/^\[RRT(-N)?\]\s*/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

export function findPlayer(players, nickname) {
  if (!players || !nickname) return null;
  if (players[nickname]) return players[nickname];

  const target = nickname.trim().toLowerCase();
  const targetClean = normalizeNick(nickname).toLowerCase();
  const keys = Object.keys(players);

  let key = keys.find((k) => k.trim().toLowerCase() === target);
  if (key) return players[key];

  key = keys.find((k) => normalizeNick(k).toLowerCase() === targetClean);
  if (key) return players[key];

  key = keys.find((k) => {
    const nk = normalizeNick(k).toLowerCase();
    return nk.startsWith(targetClean + ' ') || nk === targetClean;
  });
  if (key) return players[key];

  key = keys.find((k) => {
    const nk = normalizeNick(k).toLowerCase();
    return targetClean.startsWith(nk + ' ') || targetClean === nk;
  });
  if (key) return players[key];

  return null;
}

// Экспортируем функцию загрузки всех данных — пригодится в Roster
export async function fetchAllStats() {
  const res = await fetch(STATS_URL + '?t=' + Date.now());
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

// ============ ЛИЧНАЯ СТАТИСТИКА (5 ячеек) ============
export default function Stats({ nickname }) {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchAllStats()
      .then((data) => {
        if (cancelled) return;
        const s = findPlayer(data?.players, nickname);
        if (!s) {
          setError('Игрок не найден в статистике');
          setStats(null);
        } else {
          setStats(s);
        }
      })
      .catch((e) => {
        if (cancelled) return;
        console.error('stats fetch failed:', e);
        setError('Не удалось загрузить статистику');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [nickname]);

  if (loading) {
    return (
      <div className="card">
        <h3>Статистика</h3>
        <p className="muted">Загрузка...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="card">
        <h3>Статистика</h3>
        <div className="notice danger">{error}</div>
      </div>
    );
  }

  const kills = stats.kills ?? 0;
  const deaths = stats.deaths ?? 0;
  const kd = stats.kd ?? 0;
  const teamkills = stats.teamkills ?? 0;
  const gamesTotal = stats.games_total ?? 0;

  return (
    <div className="card">
      <h3>Статистика · {nickname}</h3>
      <div className="grid" style={{ marginTop: 14 }}>
        <div className="card stat-cell" style={{ padding: 16 }}>
          <h3>Убийства</h3>
          <div className="stat">{kills}</div>
        </div>
        <div className="card stat-cell" style={{ padding: 16 }}>
          <h3>Смерти</h3>
          <div className="stat">{deaths}</div>
        </div>
        <div className="card stat-cell" style={{ padding: 16 }}>
          <h3>K/D</h3>
          <div className="stat">{kd}</div>
        </div>
        <div className="card stat-cell" style={{ padding: 16 }}>
          <h3>Тимкиллы</h3>
          <div className="stat">{teamkills}</div>
        </div>
        <div className="card stat-cell" style={{ padding: 16 }}>
          <h3>Всего игр</h3>
          <div className="stat">{gamesTotal}</div>
        </div>
      </div>
    </div>
  );
}