import React, { useState } from 'react';
import { LOGO_SQUARE } from '../mock/data';
import {
  login, activate, requestActivation,
} from '../mock/store';

export default function Login({ onLogin }) {
  const [mode, setMode] = useState('login');
  const [uid, setUid] = useState('');
  const [pw, setPw] = useState('');
  const [pw2, setPw2] = useState('');
  const [code, setCode] = useState('');
  const [msg, setMsg] = useState(null);

  const doLogin = (e) => {
    e && e.preventDefault();
    setMsg(null);
    try {
      const u = login(uid, pw);
      onLogin(u);
    } catch (err) {
      setMsg({ type: 'danger', text: err.message });
    }
  };

  const doRequestCode = () => {
    setMsg(null);
    try {
      requestActivation(uid);
      setMsg({ type: 'good', text: 'Заявка отправлена Штабу. Как только её одобрят — вы получите код от Штаба лично.' });
    } catch (err) {
      setMsg({ type: 'danger', text: err.message });
    }
  };

  const doActivate = (e) => {
    e && e.preventDefault();
    setMsg(null);
    if (pw !== pw2) return setMsg({ type: 'danger', text: 'Пароли не совпадают' });
    if (pw.length < 4) return setMsg({ type: 'danger', text: 'Пароль слишком короткий (минимум 4 символа)' });
    try {
      const u = activate(uid, code, pw);
      onLogin(u);
    } catch (err) {
      setMsg({ type: 'danger', text: err.message });
    }
  };

  return (
    <div className="login-wrap">
      {/* Фоновое видео */}
      <video
        autoPlay
        loop
        muted
        playsInline
        className="login-bg-video"
      >
        <source src="/rrt-coin-ani.mp4" type="video/mp4" />
      </video>

      {/* Карточка логина */}
      <div className="login-card">
        <img className="login-logo" src={LOGO_SQUARE} alt="RRT" />
        <h1>RAPID RESPONSE TEAM</h1>
        <p className="login-sub">Закрытый портал подразделения</p>

        <div className="tabs">
          <button
            className={mode === 'login' ? 'active' : ''}
            onClick={() => { setMode('login'); setMsg(null); }}
          >
            Вход
          </button>
          <button
            className={mode === 'activate' ? 'active' : ''}
            onClick={() => { setMode('activate'); setMsg(null); }}
          >
            Первый вход
          </button>
        </div>

        {msg && <div className={`notice ${msg.type}`}>{msg.text}</div>}

        {mode === 'login' ? (
          <form onSubmit={doLogin}>
            <div className="field">
              <label>Discord User ID</label>
              <input
                value={uid}
                onChange={(e) => setUid(e.target.value)}
                autoComplete="username"
                placeholder="Ваш ID из Discord"
              />
            </div>
            <div className="field">
              <label>Пароль</label>
              <input
                type="password"
                value={pw}
                onChange={(e) => setPw(e.target.value)}
                autoComplete="current-password"
              />
            </div>
            <button className="btn red wide" type="submit">Войти</button>
          </form>
        ) : (
          <form onSubmit={doActivate}>
            <div className="notice" style={{ marginBottom: 12 }}>
              Шаг 1: введите свой Discord ID и запросите код у Штаба.<br />
              Шаг 2: получите код лично от Штаба.<br />
              Шаг 3: введите код и придумайте пароль.
            </div>

            <div className="field">
              <label>Discord User ID</label>
              <input
                value={uid}
                onChange={(e) => setUid(e.target.value)}
                placeholder="Ваш ID из Discord"
              />
            </div>

            <button
              type="button"
              className="btn ghost wide"
              onClick={doRequestCode}
              disabled={!uid.trim()}
              style={{ marginBottom: 12 }}
            >
              Запросить код у Штаба
            </button>

            <div className="field">
              <label>Одноразовый код (от Штаба)</label>
              <input
                value={code}
                onChange={(e) => setCode(e.target.value)}
                placeholder="ABC123"
              />
            </div>
            <div className="field">
              <label>Новый пароль</label>
              <input
                type="password"
                value={pw}
                onChange={(e) => setPw(e.target.value)}
                autoComplete="new-password"
              />
            </div>
            <div className="field">
              <label>Повторите пароль</label>
              <input
                type="password"
                value={pw2}
                onChange={(e) => setPw2(e.target.value)}
                autoComplete="new-password"
              />
            </div>
            <button className="btn red wide" type="submit">Активировать</button>
          </form>
        )}
      </div>
    </div>
  );
}