const ROLE_RANK = { marshal: 5, colonel_general: 5, lieutenant_general: 5, major: 5, captain: 4, lieutenant: 4, second_lieutenant: 4, senior_sergeant: 3, sergeant: 3, junior_sergeant: 3, corporal: 3, recruit: 2, ticket: 1 };

function isStaffLevel(user) {
  return (user?.level || ROLE_RANK[user?.accessRole] || 0) >= 5;
}

function buildNav(user) {
  const r = user.level || ROLE_RANK[user.accessRole] || 0;
  if (r === 1) return [{ id: 'questionnaire', t: 'Опросник', icon: ClipboardList }];
  const items = [
    { id: 'home', t: 'Главная', icon: Shield },
    { id: 'cabinet', t: 'Личный кабинет', icon: User },
    { id: 'roster', t: 'Состав отряда', icon: Users },
    { id: 'questionnaire', t: 'Опросник', icon: ClipboardList },
    { id: 'guide', t: 'Руководства', icon: BookOpen },
    { id: 'rules', t: 'Устав и правила', icon: ScrollText },
  ];
  if (r >= 5) items.push({ id: 'admin', t: 'Панель администратора', icon: Cog });
  return items;
}

function yearsDeclension(y) {
  const mod10 = y % 10, mod100 = y % 100;
  if (mod10 === 1 && mod100 !== 11) return 'год';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return 'года';
  return 'лет';
}
function serviceDays(s) {
  if (!s) return 0;
  return Math.max(0, Math.floor((Date.now() - new Date(s + 'T00:00:00')) / 86400000));
}
function monthsLabel(d) {
  const m = Math.floor(d / 30.4375);
  const y = Math.floor(m / 12);
  const r = m % 12;
  if (y > 0) return `${y} ${yearsDeclension(y)}${r ? ' ' + r + ' мес.' : ''}`;
  return `${m} мес.`;
}
function formatDate(s) {
  if (!s) return '—';
  return new Date(s + 'T00:00:00').toLocaleDateString('ru-RU');
}
function formatBirthDate(s) {
  if (!s) return '—';
  const parts = s.split('-');
  if (parts.length === 3) return `${parts[2]}.${parts[1]}`;
  if (parts.length === 2) return `${parts[1]}.${parts[0]}`;
  return s;
}

// ============ AVATAR ============
function Avatar({ user, size = 40 }) {
  const url = getAvatarUrl(user);
  const initials = (user?.nickname || '??').slice(0, 2).toUpperCase();
  const [failed, setFailed] = useState(false);

  useEffect(() => { setFailed(false); }, [url]);

  const hasRealAvatar = url && (
    url.includes('cdn.discordapp.com') ||
    (!url.includes('dicebear') && url.startsWith('http'))
  );

  if (failed || !hasRealAvatar) {
    return (
      <div style={{
        width: size, height: size, borderRadius: size > 60 ? 8 : '50%',
        display: 'grid', placeItems: 'center',
        background: 'linear-gradient(140deg, var(--olive), var(--red-dark))',
        border: '2px solid var(--gold-dim)',
        color: 'var(--gold)', fontWeight: 700,
        fontFamily: 'Rajdhani, sans-serif',
        fontSize: Math.max(12, size / 2.8),
        letterSpacing: 1, flexShrink: 0,
      }}>
        {initials}
      </div>
    );
  }
  return (
    <img src={url} alt={user.nickname} onError={() => setFailed(true)}
      style={{
        width: size, height: size,
        borderRadius: size > 60 ? 8 : '50%',
        objectFit: 'cover',
        border: '2px solid var(--gold-dim)',
        background: 'var(--panel-2)',
        flexShrink: 0,
      }} />
  );
}

// ============ USER LINKS ============
function UserLinks({ userId, canEdit }) {
  const [links, setLinks] = useState(() => getUserLinks(userId));
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(links);

  useEffect(() => {
    setLinks(getUserLinks(userId));
    setDraft(getUserLinks(userId));
  }, [userId]);

  const addRow = () => { if (draft.length < 5) setDraft([...draft, { title: '', url: '' }]); };
  const removeRow = (i) => setDraft(draft.filter((_, idx) => idx !== i));
  const updateRow = (i, key, val) => {
    const next = [...draft];
    next[i] = { ...next[i], [key]: val };
    setDraft(next);
  };
  const save = () => {
    const clean = draft.filter((l) => l.title?.trim() && l.url?.trim());
    setUserLinks(userId, clean);
    setLinks(clean);
    setDraft(clean);
    setEditing(false);
  };
  const cancel = () => { setDraft(links); setEditing(false); };

  return (
    <div className="card links-block">
      <div className="links-block-head">
        <h3>
          <Link2 size={16} style={{ verticalAlign: 'middle', marginRight: 8 }} />
          Мои ссылки <span className="muted" style={{ fontSize: 12 }}>({links.length}/5)</span>
        </h3>
        {canEdit && !editing && (
          <button className="btn ghost sm" onClick={() => setEditing(true)}>
            <Plus size={12} style={{ verticalAlign: 'middle', marginRight: 4 }} /> Изменить
          </button>
        )}
      </div>
      {!editing && (
        <>
          {links.length === 0 ? <p className="muted">Ссылок пока нет.</p> : (
            <div className="user-links-list">
              {links.map((l, i) => (
                <a key={i} className="user-link" href={l.url} target="_blank" rel="noreferrer">
                  <ExternalLink size={14} />
                  <span className="user-link-title">{l.title}</span>
                  <span className="user-link-url">{l.url}</span>
                </a>
              ))}
            </div>
          )}
        </>
      )}
      {editing && (
        <div className="links-editor">
          {draft.map((l, i) => (
            <div className="link-edit-row" key={i}>
              <input placeholder="Название (напр. Steam)" value={l.title} onChange={(e) => updateRow(i, 'title', e.target.value)} />
              <input placeholder="https://..." value={l.url} onChange={(e) => updateRow(i, 'url', e.target.value)} />
              <button className="icon-btn danger" onClick={() => removeRow(i)} title="Удалить"><Trash2 size={14} /></button>
            </div>
          ))}
          {draft.length < 5 && (
            <button className="btn ghost sm" onClick={addRow} style={{ marginTop: 8 }}>
              <Plus size={12} style={{ verticalAlign: 'middle', marginRight: 4 }} /> Добавить ссылку
            </button>
          )}
          <div className="links-editor-actions">
            <button className="btn" onClick={save}>
              <Save size={12} style={{ verticalAlign: 'middle', marginRight: 4 }} /> Сохранить
            </button>
            <button className="btn ghost" onClick={cancel}>Отмена</button>
          </div>
        </div>
      )}
    </div>
  );
}

