// ============ ROSTER ============
function Roster({ onOpenProfile }) {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [totals, setTotals] = useState(null);

  useEffect(() => {
    let cancelled = false;

    Promise.all([
      import('../mock/store').then(({ fetchRoster }) => fetchRoster()),
      import('./Stats').then(({ fetchAllStats, findPlayer }) =>
        fetchAllStats().then((data) => ({ data, findPlayer }))
      ),
    ])
      .then(([rosterList, { data, findPlayer }]) => {
        if (cancelled) return;
        setUsers(rosterList);

        // Считаем общие суммы по всем игрокам
        const players = data?.players || {};
        let kills = 0, deaths = 0, teamkills = 0, games = 0;
        let matched = 0;

        rosterList.forEach((u) => {
          const s = findPlayer(players, u.nickname);
          if (!s) return;
          matched++;
          kills += s.kills ?? 0;
          deaths += s.deaths ?? 0;
          teamkills += s.teamkills ?? 0;
          games += s.games_total ?? 0;
        });

        const kd = deaths > 0 ? +(kills / deaths).toFixed(2) : kills;
        setTotals({ kills, deaths, kd, teamkills, games, matched });
      })
      .catch((e) => { if (!cancelled) setError(e.message); })
      .finally(() => { if (!cancelled) setLoading(false); });

    return () => { cancelled = true; };
  }, []);

  if (loading) return <div className="card"><h2>Состав отряда</h2><p className="muted">Загрузка данных из Discord…</p></div>;
  if (error) return (
    <div className="card">
      <h2>Состав отряда</h2>
      <div className="notice danger">
        <b>Не удалось загрузить состав</b>
        <div style={{ marginTop: 6, fontFamily: 'JetBrains Mono, monospace', fontSize: 12 }}>{error}</div>
      </div>
    </div>
  );

  return (
    <>
      {/* ====== ОБЩАЯ СТАТИСТИКА ОТРЯДА ====== */}
      {totals && (
        <div className="card">
          <h2>Общая статистика отряда</h2>
          <p className="muted">
            Данные по <b>{totals.matched}</b> из <b>{users.length}</b> игроков
          </p>
          <div className="grid" style={{ marginTop: 14 }}>
            <div className="card stat-cell" style={{ padding: 16 }}>
              <h3>Всего убийств</h3>
              <div className="stat">{totals.kills}</div>
            </div>
            <div className="card stat-cell" style={{ padding: 16 }}>
              <h3>Всего смертей</h3>
              <div className="stat">{totals.deaths}</div>
            </div>
            <div className="card stat-cell" style={{ padding: 16 }}>
              <h3>Общий K/D</h3>
              <div className="stat">{totals.kd}</div>
            </div>
            <div className="card stat-cell" style={{ padding: 16 }}>
              <h3>Всего тимкиллов</h3>
              <div className="stat">{totals.teamkills}</div>
            </div>
            <div className="card stat-cell" style={{ padding: 16 }}>
              <h3>Игр (сумма)</h3>
              <div className="stat">{totals.games}</div>
            </div>
          </div>
        </div>
      )}

      <div className="spacer" />

      {/* ====== ТАБЛИЦА СОСТАВА ====== */}
      <div className="card">
        <h2>Состав отряда</h2>
        <p className="muted">Всего в составе: <b>{users.length}</b> · данные из Discord</p>
        <div className="table-wrap">
          <table className="table">
            <thead>
              <tr><th>#</th><th>Игрок</th><th>Discord ID</th><th>Звание</th><th>В отряде</th><th>Все роли</th></tr>
            </thead>
            <tbody>
              {users.map((u, i) => {
                const topRole = u.discordRoles?.[0] || u.topRole || '—';
                return (
                  <tr key={u.id}>
                    <td className="muted mono">{i + 1}</td>
                    <td>
                      <button className="roster-nick-btn" onClick={() => onOpenProfile(u.id)}>
                        <Avatar user={u} size={26} />
                        <b>{u.nickname}</b>
                      </button>
                    </td>
                    <td className="mono" style={{ fontSize: 12 }}>{u.id}</td>
                    <td><span className="badge olive">{topRole}</span></td>
                    <td>{u.joinedAt ? serviceDays(u.joinedAt) + ' дней' : '—'}</td>
                    <td className="muted" style={{ fontSize: 12 }}>{u.discordRoles.join(', ') || '—'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

// ============ RULES ============
function Rules() {
  const lines = RULES_TEXT.split('\n');
  const sections = [];
  let current = { title: null, items: [] };
  lines.forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed) return;
    const isHeader = /^[А-ЯЁA-Z][^.]*:$/.test(trimmed) || /^[А-ЯЁ\s]+$/.test(trimmed);
    if (isHeader && !/^\d/.test(trimmed)) {
      if (current.items.length || current.title) sections.push({ ...current });
      current = { title: trimmed.replace(/:$/, ''), items: [] };
    } else {
      current.items.push(trimmed);
    }
  });
  if (current.items.length || current.title) sections.push(current);

  return (
    <div className="card rules-card">
      <h2>Устав и правила</h2>
      <p className="rules-intro">Доброго времени суток, РЕКРУТ! Ознакомься с правилами ниже.</p>
      <div className="rules-sections">
        {sections.map((s, i) => (
          <div key={i} className="rules-section">
            {s.title && <h3 className="rules-section-title">{s.title}</h3>}
            <ul className="rules-list">
              {s.items.map((item, j) => <li key={j} className="rules-item">{item}</li>)}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
}

// ============ QUESTIONNAIRE ============
function Questionnaire({ user }) {
  const q = QUESTIONNAIRE;
  const [values, setValues] = useState({});
  const [done, setDone] = useState(false);
  const submit = (e) => { e.preventDefault(); addSubmission(user, values); setDone(true); };

  if (done) {
    return (
      <div className="card">
        <h2>{q.title}</h2>
        <div className="notice good">✓ Опросник отправлен. Штаб свяжется с вами в Discord.</div>
        <div className="spacer" />
        <button className="btn ghost" onClick={() => { setDone(false); setValues({}); }}>
          Заполнить заново
        </button>
      </div>
    );
  }

  return (
    <div className="card form">
      <div className="q-header">
        <h2>{q.title}</h2>
        <p className="muted">{q.description}</p>
      </div>
      <form onSubmit={submit}>
        {q.sections.map((section) => (
          <div key={section.id} className="q-section">
            <div className="q-section-title">
              <span className="q-section-num">{section.id}</span>
              <h3>{section.title}</h3>
            </div>
            {section.subtitle && <p className="q-section-sub">{section.subtitle}</p>}
            {section.questions.map((qq) => (
              <div className="field" key={qq.id}>
                <label>{qq.text}{qq.required && <span className="req"> *</span>}</label>
                {qq.type === 'textarea' && (
                  <textarea rows={4} required={qq.required} value={values[qq.id] || ''}
                    onChange={(e) => setValues((v) => ({ ...v, [qq.id]: e.target.value }))} />
                )}
                {qq.type === 'input' && (
                  <input required={qq.required} value={values[qq.id] || ''}
                    onChange={(e) => setValues((v) => ({ ...v, [qq.id]: e.target.value }))} />
                )}
                {qq.type === 'select' && (
                  <select required={qq.required} value={values[qq.id] || ''}
                    onChange={(e) => setValues((v) => ({ ...v, [qq.id]: e.target.value }))}>
                    <option value="">Выберите...</option>
                    {qq.options.map((o) => <option key={o}>{o}</option>)}
                  </select>
                )}
                {qq.type === 'radio' && (
                  <>
                    {qq.options.every((o) => /^\d+$/.test(o)) && qq.options.length === 10 ? (
                      <div className="radio-scale">
                        {qq.options.map((o) => (
                          <label key={o} className={`scale-cell ${values[qq.id] === o ? 'picked' : ''}`}>
                            <input type="radio" name={`q_${qq.id}`} value={o}
                              checked={values[qq.id] === o}
                              onChange={(e) => setValues((v) => ({ ...v, [qq.id]: e.target.value }))}
                              required={qq.required} />
                            <span>{o}</span>
                          </label>
                        ))}
                      </div>
                    ) : (
                      <div className="radio-group">
                        {qq.options.map((o) => (
                          <label key={o} className={`radio-row ${values[qq.id] === o ? 'picked' : ''}`}>
                            <input type="radio" name={`q_${qq.id}`} value={o}
                              checked={values[qq.id] === o}
                              onChange={(e) => setValues((v) => ({ ...v, [qq.id]: e.target.value }))}
                              required={qq.required} />
                            <span>{o}</span>
                          </label>
                        ))}
                      </div>
                    )}
                  </>
                )}
              </div>
            ))}
          </div>
        ))}
        <div className="spacer" />
        <button className="btn red" type="submit">Отправить</button>
      </form>
    </div>
  );
}

// ============ GUIDES ============
function GuideCenter({ user }) {
  const [guideKey, setGuideKey] = useState(null);
  const [blockIndex, setBlockIndex] = useState(0);
  const [qIndex, setQIndex] = useState(0);
  const [feedback, setFeedback] = useState(null);
  const [flash, setFlash] = useState('');
  const [, setTick] = useState(0);
  const guides = GUIDES;

  if (!guideKey) {
    return (
      <div className="card">
        <h2>Руководства</h2>
        <p className="muted">Сначала теория, затем короткая проверка только по этому блоку.</p>
        <div className="guide-list">
          {[['ace_medical', 'ACE Medical', 'Медицина ACE. 10 блоков.'],
            ['movement', 'Порядок движения', 'Марш, контакт, триггер, здания и траншеи. 7 блоков.']]
            .map(([k, t, s]) => {
              const prog = getGuideProgress(user.id, k);
              const total = guides[k].length;
              const done = Object.values(prog).filter((p) => p.completed).length;
              return (
                <div key={k} className="card">
                  <h3>{t}</h3><p>{s}</p>
                  <div className="progress-mini">Прогресс: {done} / {total} блоков</div>
                  <div className="stepper">
                    {guides[k].map((b) => {
                      const p = prog[b.id] || {};
                      return <div key={b.id} className={`step ${p.completed ? 'done' : ''} ${p.locked ? 'locked' : ''}`} />;
                    })}
                  </div>
                  <div style={{ marginTop: 14 }}>
                    <button className="btn red" onClick={() => {
                      setGuideKey(k);
                      const idx = guides[k].findIndex((b) => !(prog[b.id]?.completed));
                      setBlockIndex(idx < 0 ? 0 : idx);
                      setQIndex(0); setFeedback(null); setFlash('');
                    }}>Открыть</button>
                  </div>
                </div>
              );
            })}
        </div>
      </div>
    );
  }

  const blocks = guides[guideKey];
  const block = blocks[blockIndex];
  const progress = getGuideProgress(user.id, guideKey);
  const bp = progress[block.id] || { wrong_count: 0, resets: 0, locked: false, completed: false };
  const question = block.questions[qIndex];
  const back = () => { setGuideKey(null); setFeedback(null); setFlash(''); };
  const answer = (idx) => {
    if (feedback) return;
    const correct = idx === question.correct;
    if (correct) {
      setFeedback({ good: true, text: question.explanation });
      setTimeout(() => {
        if (qIndex >= block.questions.length - 1) {
          setBlockProgress(user.id, guideKey, block.id, { completed: true, wrong_count: 0 });
          setFeedback(null);
          if (blockIndex < blocks.length - 1) { setBlockIndex(blockIndex + 1); setQIndex(0); }
          else { setFlash('Руководство полностью пройдено.'); setGuideKey(null); }
        } else { setQIndex(qIndex + 1); setFeedback(null); }
      }, 900);
    } else {
      const wc = (bp.wrong_count || 0) + 1;
      if (wc >= 3) {
        const resets = (bp.resets || 0) + 1;
        if (resets >= 3) {
          setBlockProgress(user.id, guideKey, block.id, { wrong_count: 0, resets, locked: true });
          setFeedback({ good: false, text: question.explanation, locked: true });
        } else {
          setBlockProgress(user.id, guideKey, block.id, { wrong_count: 0, resets });
          setFeedback({ good: false, text: question.explanation, reset: true, lastAttempt: resets === 2 });
          setTimeout(() => { setQIndex(0); setFeedback(null); setTick((t) => t + 1); }, 2500);
        }
      } else {
        setBlockProgress(user.id, guideKey, block.id, { wrong_count: wc });
        setFeedback({ good: false, text: question.explanation, remaining: 3 - wc });
      }
      setTick((t) => t + 1);
    }
  };
  const nextQ = () => { setFeedback(null); setQIndex(qIndex + 1); };

  return (
    <div className="card">
      <button className="btn ghost sm" onClick={back}>
        <ChevronLeft size={14} style={{ verticalAlign: 'middle', marginRight: 4 }} />К руководствам
      </button>
      {flash && <div className="notice danger" style={{ marginTop: 10 }}><b>{flash}</b></div>}
      <div className="progressline">
        Блок <span className="pill">{blockIndex + 1} из {blocks.length}</span> · {bp.completed ? 'Пройден' : 'В процессе'}
        {bp.resets === 2 && <span className="warn"> · ПОСЛЕДНЯЯ ПОПЫТКА</span>}
      </div>
      <div className="stepper">
        {blocks.map((b, i) => {
          const p = progress[b.id] || {};
          return <div key={b.id} className={`step ${p.completed ? 'done' : ''} ${i === blockIndex && !p.completed ? 'now' : ''} ${p.locked ? 'locked' : ''}`} />;
        })}
      </div>
      <h2 style={{ marginTop: 10 }}>{block.title}</h2>
      <div className="theory">{block.theory}</div>
      {bp.locked ? (
        <div className="notice danger"><b>Обучение заблокировано.</b><br />Обратитесь к администратору.</div>
      ) : bp.completed ? (
        <>
          <div className="notice good">✓ Блок уже пройден.</div>
          <div className="spacer" />
          <button className="btn red" onClick={() => {
            if (blockIndex < blocks.length - 1) { setBlockIndex(blockIndex + 1); setQIndex(0); setFeedback(null); }
            else back();
          }}>Следующий блок</button>
        </>
      ) : (
        <>
          <div className="muted mono" style={{ fontSize: 12, letterSpacing: 1 }}>ВОПРОС {qIndex + 1} / {block.questions.length}</div>
          <h3 style={{ color: 'var(--text)', margin: '8px 0 6px', fontSize: 17 }}>{question.question}</h3>
          <div className="answers">
            {question.options.map((o, i) => (
              <button key={i} className="answer" disabled={!!feedback} onClick={() => answer(i)}>{o}</button>
            ))}
          </div>
          {feedback && (
            <div className={`feedback ${feedback.good ? 'good' : 'bad'}`}>
              <b>{feedback.good ? 'Правильно!' : 'Неправильно!'}</b>
              {feedback.text}
              {feedback.reset && <div style={{ marginTop: 6 }}><b>3 ошибки — возврат к теории.</b></div>}
              {feedback.lastAttempt && <div><b>У тебя последняя попытка.</b></div>}
              {feedback.locked && <div style={{ marginTop: 6 }}><b>Обучение заблокировано. Обратитесь к администратору.</b></div>}
              {!feedback.good && !feedback.reset && !feedback.locked && (
                <div style={{ marginTop: 10 }}>
                  <button className="btn ghost sm" onClick={nextQ}>Следующий вопрос</button>
                </div>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ============ ADMIN ============
function Admin() {
  const [tab, setTab] = useState(null);
  const [status, setStatus] = useState(null);
  const [issued, setIssued] = useState('');
  const users = getUsers();
  const [m, setM] = useState({ id: '', nickname: '', accessRole: 'recruit', joinedAt: '', birthDate: '', avatarUrl: '' });

  const requests = getActivationRequests();
  const pendingCount = requests.filter((r) => r.status === 'pending').length;

  const handleSelectUser = (id) => {
    const u = users.find((x) => x.id === id);
    if (!u) { setM({ id, nickname: '', accessRole: 'recruit', joinedAt: '', birthDate: '', avatarUrl: '' }); return; }
    setM({
      id: u.id, nickname: u.nickname || '', accessRole: u.accessRole || 'recruit',
      joinedAt: u.joinedAt || '', birthDate: u.birthDate || '', avatarUrl: u.avatarUrl || '',
    });
  };

  const lockedStudents = [];
  users.forEach((u) => {
    ['ace_medical', 'movement'].forEach((guideKey) => {
      const prog = getGuideProgress(u.id, guideKey);
      Object.entries(prog).forEach(([blockId, p]) => {
        if (p.locked) lockedStudents.push({ userId: u.id, nickname: u.nickname, guideKey, blockId });
      });
    });
  });

  const say = (t, k = 'good') => { setStatus({ t, k }); setTimeout(() => setStatus(null), 4000); };

  return (
    <>
      <div className="grid">
        <div className="card">
          <h3>Участники</h3>
          <p>Выбрать участника из списка и изменить данные.</p>
          <button className="btn" onClick={() => setTab('member')}>Открыть</button>
        </div>

        <div className="card">
          <div className="card-with-bell">
            <h3>Заявки на код</h3>
            {pendingCount > 0 && <span className="bell"><Bell size={14} /> {pendingCount}</span>}
          </div>
          <p>Запросы новичков на одноразовый код активации.</p>
          <button className="btn" onClick={() => setTab('requests')}>Открыть</button>
        </div>

        <div className="card">
          <h3>Опросники</h3>
          <p>Просмотр отправленных анкет.</p>
          <button className="btn" onClick={() => setTab('subs')}>Открыть</button>
        </div>

        <div className="card">
          <h3>Discord</h3>
          <p>Синхронизация состава (демо).</p>
          <button className="btn" onClick={() => say('Синхронизация выполнена (демо). Обновлено ' + users.length + ' уч.')}>
            <RefreshCw size={14} style={{ verticalAlign: 'middle', marginRight: 6 }} /> Синхронизировать
          </button>
        </div>

        <div className="card">
          <div className="card-with-bell">
            <h3>Попытки обучения</h3>
            {lockedStudents.length > 0 && <span className="bell"><Bell size={14} /> {lockedStudents.length}</span>}
          </div>
          <p>Кому нужен сброс попыток — список готов.</p>
          <button className="btn" onClick={() => setTab('reset')}>Открыть</button>
        </div>
      </div>

      <div className="spacer" />
      {status && <div className={`notice ${status.k === 'good' ? 'good' : 'danger'}`}>{status.t}</div>}
      {issued && <div className="notice" style={{ marginTop: 10 }}>Одноразовый код: <b className="mono">{issued}</b></div>}

      {tab === 'member' && (
        <div className="card form" style={{ marginTop: 16 }}>
          <h3>Участник</h3>
          <div className="field">
            <label>Выбрать участника</label>
            <select value={m.id} onChange={(e) => handleSelectUser(e.target.value)}>
              <option value="">— выберите из списка —</option>
              {users.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.nickname} · {ACCESS_ROLES[u.accessRole] || u.accessRole}
                </option>
              ))}
            </select>
          </div>

          {m.id && (
            <>
              <div className="notice" style={{ marginBottom: 12 }}>Discord ID: <b className="mono">{m.id}</b></div>
              <div className="field">
                <label>Ник</label>
                <input value={m.nickname} onChange={(e) => setM({ ...m, nickname: e.target.value })} />
              </div>
              <div className="field">
                <label>Роль доступа</label>
                <select value={m.accessRole} onChange={(e) => setM({ ...m, accessRole: e.target.value })}>
                  {Object.entries(ACCESS_ROLES).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                </select>
              </div>
              <div className="field">
                <label>Дата вступления</label>
                <CalendarInput
                  value={m.joinedAt || ''}
                  onChange={(v) => setM({ ...m, joinedAt: v })}
                  mode="full"
                  placeholder="ДД.ММ.ГГГГ"
                />
              </div>
              <div className="field">
                <label>День рождения (ДД.ММ)</label>
                <CalendarInput
                  value={m.birthDate || ''}
                  onChange={(v) => setM({ ...m, birthDate: v })}
                  mode="month-day"
                  placeholder="ДД.ММ"
                />
              </div>
              <div className="field">
                <label>Avatar URL (опционально)</label>
                <input placeholder="https://..." value={m.avatarUrl || ''} onChange={(e) => setM({ ...m, avatarUrl: e.target.value })} />
              </div>

              <button className="btn" onClick={() => {
                if (!m.id || !m.nickname) return say('Выберите участника', 'danger');
                upsertMember(m);
                say('Сохранено');
              }}>Сохранить</button>{' '}
              <button className="btn ghost" onClick={() => {
                if (!m.id) return say('Выберите участника', 'danger');
                try {
                  const code = issueActivation(m.id);
                  setIssued(code);
                  say('Код выдан');
                } catch (err) { say(err.message, 'danger'); }
              }}>Выдать код активации</button>
            </>
          )}
        </div>
      )}

      {tab === 'requests' && (
        <div className="card" style={{ marginTop: 16 }}>
          <h3>Заявки на код активации</h3>
          {requests.length === 0 ? <p className="muted">Пока нет заявок.</p> : (
            <div className="locked-list">
              {requests.map((r, i) => {
                const u = users.find((x) => x.id === r.userId);
                const displayName = u?.nickname || u?.displayName || r.nickname || r.userId;
                return (
                  <div key={i} className="locked-row">
                    <div style={{ flex: 1, minWidth: 200 }}>
                      <b>{displayName}</b>
                      <span className="muted mono" style={{ marginLeft: 8, fontSize: 12 }}>{r.userId}</span>
                      <div className="muted" style={{ fontSize: 12, marginTop: 4 }}>{new Date(r.createdAt).toLocaleString('ru-RU')}</div>
                    </div>
                    {r.status === 'pending' ? (
                      <div style={{ display: 'flex', gap: 8 }}>
                        <button className="btn sm" onClick={() => {
                          try {
                            const code = approveActivation(r.userId);
                            setIssued(code);
                            say('Код для ' + displayName + ': ' + code);
                            setTab(null); setTimeout(() => setTab('requests'), 50);
                          } catch (err) { say(err.message, 'danger'); }
                        }}>Одобрить</button>
                        <button className="btn red sm" onClick={() => {
                          rejectActivation(r.userId);
                          say('Заявка отклонена');
                          setTab(null); setTimeout(() => setTab('requests'), 50);
                        }}>Отклонить</button>
                      </div>
                    ) : (
                      <div className={`badge ${r.status === 'approved' ? 'olive' : 'red'}`}>
                        {r.status === 'approved' ? 'Одобрена' : 'Отклонена'}
                        {r.code && r.status === 'approved' && <span className="mono" style={{ marginLeft: 6 }}>{r.code}</span>}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {tab === 'subs' && (
        <div className="card" style={{ marginTop: 16 }}>
          <h3>Ответы</h3>
          <div className="table-wrap">
            <table className="table">
              <thead><tr><th>Дата</th><th>Nickname</th><th>ID</th><th>Опросник</th></tr></thead>
              <tbody>
                {getSubmissions().map((x, i) => (
                  <tr key={i}>
                    <td>{new Date(x.submitted_at * 1000).toLocaleString('ru-RU')}</td>
                    <td>{x.nickname}</td>
                    <td className="mono" style={{ fontSize: 12 }}>{x.user_id}</td>
                    <td>{x.title}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === 'reset' && (
        <div className="card form" style={{ marginTop: 16 }}>
          <h3>Сброс попыток</h3>
          {lockedStudents.length === 0 ? <p className="muted">Никому сейчас не нужен сброс.</p> : (
            <div className="locked-list">
              {lockedStudents.map((s, i) => (
                <div key={i} className="locked-row">
                  <div>
                    <b>{s.nickname}</b>
                    <span className="muted mono" style={{ marginLeft: 8, fontSize: 12 }}>{s.userId}</span>
                  </div>
                  <div className="muted" style={{ fontSize: 12 }}>
                    {s.guideKey === 'ace_medical' ? 'ACE Medical' : 'Порядок движения'}, блок #{s.blockId}
                  </div>
                  <button className="btn red sm" onClick={() => {
                    resetBlockProgress(s.userId, s.guideKey, Number(s.blockId));
                    say('Попытки сброшены у ' + s.nickname);
                    setTab(null); setTimeout(() => setTab('reset'), 50);
                  }}>Сбросить</button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </>
  );
}

// ============ MODAL PROFILE ============
function ProfileModal({ userId, viewer, onClose }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    import('../mock/store').then(({ fetchRoster }) => {
      fetchRoster()
        .then((list) => {
          if (cancelled) return;
          setUser(list.find((x) => x.id === userId) || null);
        })
        .catch(() => {})
        .finally(() => { if (!cancelled) setLoading(false); });
    });
    return () => { cancelled = true; };
  }, [userId]);

  if (loading || !user) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-window" onClick={(e) => e.stopPropagation()}>
        <button className="modal-close" onClick={onClose}><X size={18} /></button>
        <div className="modal-body">
          <Cabinet user={user} viewer={viewer} />
        </div>
      </div>
    </div>
  );
}

// ============ PORTAL ============
export default function Portal({ user, onLogout }) {
  const [page, setPage] = useState('home');
  const [profileId, setProfileId] = useState(null);
  const [selfUser, setSelfUser] = useState(user);

  useEffect(() => {
    let cancelled = false;
    import('../mock/store').then(({ fetchRoster }) => {
      fetchRoster()
        .then((list) => {
          if (cancelled) return;
          const me = list.find((x) => x.id === user.id);
          if (!me) return;

          setSelfUser((prev) => ({
            ...prev,
            // Из Discord — только актуальные данные о ролях и нике Discord:
            discordRoles: me.discordRoles,
            discordUsername: me.discordUsername,
            discordGlobalName: me.discordGlobalName,
            discordJoinedAt: me.discordJoinedAt,
            level: me.level,
            // avatarUrl из Discord — только если свой не задан в админке:
            avatarUrl: (prev.avatarUrl && prev.avatarUrl.trim())
              ? prev.avatarUrl
              : (me.avatarUrl || ''),
            // ВАЖНО: nickname, accessRole, joinedAt, birthDate — берём из localStorage,
            //          их перезаписывать нельзя (иначе правки из админки слетят).
          }));
        })
        .catch(() => {});
    });
    return () => { cancelled = true; };
  }, [user.id]);

  const items = buildNav(selfUser);
  const activeItem = items.find((x) => x.id === page) || items[0];
  const topRole = selfUser.discordRoles?.[0] || ACCESS_ROLES[selfUser.accessRole] || selfUser.accessRole || '—';
  const doLogout = () => { logout(); onLogout(); };

  return (
    <div className="shell">
      <aside className="sidebar">
        <div className="brand">
          <img src={LOGO_SQUARE} alt="RRT" />
          <h1>RAPID RESPONSE TEAM</h1>
          <p>UNIT PORTAL</p>
        </div>
        <div className="nav">
          {items.map((x) => {
            const Icon = x.icon;
            return (
              <button key={x.id} className={activeItem.id === x.id ? 'active' : ''} onClick={() => setPage(x.id)}>
                <Icon size={15} />{x.t}
              </button>
            );
          })}
          <button className="logout" onClick={doLogout}><LogOut size={15} />Выйти</button>
        </div>
      </aside>

      <main className="main">
        <header className="top">
          <div />
          <div className="title">[RRT] / {activeItem.t.toUpperCase()}</div>
          <div className="user-chip">
            <div style={{ textAlign: 'right' }}>
              <div>{selfUser.nickname}</div>
              <div className="role">{topRole}</div>
            </div>
            <Avatar user={selfUser} size={40} />
          </div>
        </header>

        <section className="content">
          {activeItem.id === 'home' && <Home user={selfUser} />}
          {activeItem.id === 'cabinet' && <Cabinet user={selfUser} viewer={selfUser} />}
          {activeItem.id === 'roster' && <Roster onOpenProfile={setProfileId} />}
          {activeItem.id === 'rules' && <Rules />}
          {activeItem.id === 'questionnaire' && <Questionnaire user={selfUser} />}
          {activeItem.id === 'guide' && <GuideCenter user={selfUser} />}
          {activeItem.id === 'admin' && <Admin />}
        </section>
      </main>

      {profileId && (
        <ProfileModal userId={profileId} viewer={selfUser} onClose={() => setProfileId(null)} />
      )}
    </div>
  );
}